contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes memory data) public payable {
        address callee = address(this);
        uint256 calleeBefore = callee.balance;
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 calleeAfter = callee.balance;
        assert(calleeAfter == calleeBefore);
    }
    receive() external payable {}
    fallback() external payable {}
}

