pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(bytes memory data) internal {
        address callee = address(this);
        uint256 calleeBefore = callee.balance;
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 calleeAfter = callee.balance;
        assertTrue(calleeAfter == calleeBefore);
    }

    function testFuzz_run(bytes memory data) public {
        _run(data);
    }

    receive() external payable {}

    fallback() external payable {}
}
